 function validate(a,ps){
  const e=[];
  if(!a.name?.trim())e.push('请填写 Agent 名称');
  if(!a.description?.trim())e.push('请填写职责说明');
  if(!P.modules.some(m=>m.id===a.module))e.push('所属模块无效');
  if(!['draft','enabled','disabled'].includes(a.status))e.push('状态无效');
  if(!Array.isArray(a.inputs)||a.inputs.some(k=>!P.vars[k]))e.push('输入数据无效');
  if(!Array.isArray(a.prompts))return [...e,'关联提示词无效'];
  const ids=new Set();
  a.prompts.forEach(p=>{const d=P.catalog.find(d=>d.id===p.id);if(!d||d.module!==a.module){e.push('只能关联所属模块的提示词');return;}if(ids.has(p.id))e.push('提示词不能重复关联');ids.add(p.id);if(a.status==='enabled'&&d.variables.some(k=>!a.inputs.includes(k)))e.push('启用前请补齐关联提示词需要的输入数据');});
  if(a.status==='enabled'&&!a.prompts.length)e.push('启用前请至少关联一条提示词');
  if(a.status==='enabled'&&(!a.location?.trim()||!a.outputLocation?.trim()))e.push('启用前请填写使用位置和输出位置');
  for(const kind of kinds){if(!Array.isArray(a[kind])){e.push('配置列表格式有误');continue;}const seen=new Set();for(const r of a[kind]){if(!r.id||seen.has(r.id))e.push('配置条目标识重复或缺失');seen.add(r.id);if(!r.name?.trim())e.push('请填写条目名称');if(r.promptId&&!a.prompts.some(p=>p.id===r.promptId))e.push('请先调整引用该提示词的产物或评估，再取消关联');if(kind==='evaluations'&&!['pending','passed','failed'].includes(r.result))e.push('评估状态无效');if(kind==='evaluations'&&r.result!=='pending'&&(!r.reason?.trim()||!r.actual?.trim()))e.push('记录评估结论时请填写实际输出与判断原因');}}
  return [...new Set(e)];
 }
 function store(storage,ps){
  // Agent links identify prompts; published content is resolved when used.
  let defaults;
  function read(){const raw=storage.getItem(key);if(!raw){defaults??={schema:1,rev:0,agents:seed(ps)};return clone(defaults);}let d;try{d=JSON.parse(raw);}catch(_){throw Error('Agent 配置读取失败，原数据未覆盖。');}if(d.schema!==1||!Number.isInteger(d.rev)||!Array.isArray(d.agents)||d.agents.some(a=>!a.id||kinds.some(k=>!Array.isArray(a[k]))))throw Error('Agent 配置格式不兼容，原数据未覆盖。');return d;}
  function saveAgent(agent,rev){const d=read();if(d.rev!==rev)throw Error('配置已在其他窗口更新，请刷新后重试。');const errors=validate(agent,ps);if(errors.length)throw Error(errors.join('；'));const a=clone(agent);a.updatedAt=new Date().toISOString();const index=d.agents.findIndex(x=>x.id===a.id);if(index<0)d.agents.push(a);else d.agents[index]=a;d.rev++;try{storage.setItem(key,JSON.stringify(d));}catch(_){throw Error('保存失败，浏览器存储空间可能不足。请缩小上传文件后重试。');}return clone(d);}
  function initialize(){const d=read();const clearPromptPins=d.agents.some(a=>a.prompts.some(p=>Object.hasOwn(p,'version')));if(clearPromptPins){d.agents.forEach(a=>a.prompts.forEach(p=>delete p.version));d.rev++;}const product=d.agents.find(a=>a.id==='agent-products');const rename=product?.name==='产品分析 Agent';if(rename){product.name=names.products;if(product.description==='洞察产品表现，识别异动与营销机会。')product.description=descriptions.products;d.rev++;}const updateArtifact=product&&!product.artifactSpecVersion;if(updateArtifact){const old=product.artifacts.findIndex(r=>r.name==='产品销售总结模板'&&typeof r.markdown!=='string');if(old>=0){product.previousArtifactTemplate=clone(product.artifacts[old]);product.artifacts.splice(old,1,productArtifact());}else product.artifacts.unshift(productArtifact());product.artifactSpecVersion=1;d.rev++;}const updateEvaluation=product&&!product.evaluationSpecVersion;if(updateEvaluation){const old=product.evaluations.findIndex(r=>r.name==='事实与完整性检查'&&r.result==='pending'&&typeof r.markdown!=='string');if(old>=0){product.previousEvaluationTemplate=clone(product.evaluations[old]);product.evaluations.splice(old,1,productEvaluation());}else product.evaluations.unshift(productEvaluation());product.evaluationSpecVersion=1;d.rev++;}const updateSkill=product&&!product.skillSpecVersion;if(updateSkill){const old=product.skills.findIndex(r=>r.name==='业务信息汇总'&&typeof r.markdown!=='string');if(old>=0){product.previousSkillTemplate=clone(product.skills[old]);product.skills.splice(old,1,productSkill());}else product.skills.unshift(productSkill());product.skillSpecVersion=1;d.rev++;}const removeDocumentExamples=product&&product.documentExamplesVersion!==2;if(removeDocumentExamples){product.removedDocumentExamples=product.removedDocumentExamples||[];for(const kind of ['artifacts','evaluations','skills']){product.removedDocumentExamples.push(...product[kind].filter(r=>exampleDocumentIds.has(r.id)).map(r=>({kind,document:clone(r)})));product[kind]=product[kind].filter(r=>!exampleDocumentIds.has(r.id));}product.documentExamplesVersion=2;d.rev++;}const importKnowledge=product&&!product.knowledgeDocumentsVersion;if(importKnowledge){const placeholder=product.knowledge.findIndex(r=>r.name==='业务判断规则'&&typeof r.markdown!=='string'&&r.content==='仅依据已提供的业务记录进行分析。缺失数据不能视为零，判断与事实分开说明。');if(placeholder>=0){product.previousKnowledgeTemplate=clone(product.knowledge[placeholder]);product.knowledge.splice(placeholder,1);}for(const doc of productKnowledgeDocuments)if(!product.knowledge.some(r=>r.id===doc.id||r.filename===doc.filename))product.knowledge.push(clone(doc));product.knowledgeDocumentsVersion=1;d.rev++;}const campaign=d.agents.find(a=>a.id==='agent-campaigns');const importCreatorReferences=campaign&&!campaign.referenceDocumentsVersion;if(importCreatorReferences){const placeholder=campaign.knowledge.findIndex(r=>r.name==='业务判断规则'&&typeof r.markdown!=='string'&&['审批通过不等同于付款完成。素材质量以人工标签为准，授权以有效已签合同为准。','仅依据已提供的业务记录进行分析。缺失数据不能视为零，判断与事实分开说明。'].includes(r.content));if(placeholder>=0){campaign.previousKnowledgeTemplate=clone(campaign.knowledge[placeholder]);campaign.knowledge.splice(placeholder,1);}for(const doc of creatorReferenceDocuments)if(!campaign.knowledge.some(r=>r.id===doc.id||r.filename===doc.filename))campaign.knowledge.push(clone(doc));campaign.referenceDocumentsVersion=1;d.rev++;}const importCreatorSkill=campaign&&!campaign.creatorSkillSpecVersion;if(importCreatorSkill){const placeholder=campaign.skills.findIndex(r=>r.name==='业务信息汇总'&&typeof r.markdown!=='string'&&r.steps==='读取已提供的数据\n按主题整理事实\n标记缺失信息');if(placeholder>=0){campaign.previousSkillTemplate=clone(campaign.skills[placeholder]);campaign.skills.splice(placeholder,1);}if(!campaign.skills.some(r=>r.id===creatorSkillDocument.id||r.filename===creatorSkillDocument.filename))campaign.skills.unshift(clone(creatorSkillDocument));campaign.creatorSkillSpecVersion=1;d.rev++;}const renameCampaign=campaign?.name==='Campaign 运营 Agent';if(renameCampaign){campaign.name=names.campaigns;if(campaign.description==='跟进活动进度、合作履约与邮件沟通。')campaign.description=descriptions.campaigns;d.rev++;}const moveModule=campaign?.module==='campaigns';if(moveModule){
    const defs=P.catalog.filter(p=>p.module==='creators');
    campaign.previousModuleConfig={module:campaign.module,prompts:clone(campaign.prompts),inputs:clone(campaign.inputs)};
    campaign.module='creators';
    if(campaign.location==='Campaigns')campaign.location='Influencer CRM';
    campaign.prompts=defs.map(p=>({id:p.id}));
    campaign.inputs=[...new Set(defs.flatMap(p=>p.variables))];
    for(const kind of ['artifacts','evaluations'])for(const item of campaign[kind])if(item.promptId&&!campaign.prompts.some(p=>p.id===item.promptId)){item.previousPromptId=item.promptId;item.promptId='';}
    d.rev++;
   }const retired=d.agents.find(a=>a.id==='agent-creators'&&!a.archived);if(retired){retired.archived=true;d.rev++;}if(clearPromptPins||rename||updateArtifact||updateEvaluation||updateSkill||removeDocumentExamples||importKnowledge||importCreatorReferences||importCreatorSkill||renameCampaign||moveModule||retired||!storage.getItem(key)){try{storage.setItem(key,JSON.stringify(d));}catch(_){throw Error('无法保存 Agent 配置，请检查浏览器存储空间。');}}return clone(d);}
  return {read,initialize,saveAgent};
 }
 const api={key,kinds,uid,clone,validate,store};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.AIOSAgents=api;
